const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const santaMonicaCoast = ee.Geometry.Polygon([[
    [-118.55, 33.95], [-118.45, 33.95], 
    [-118.45, 34.05], [-118.55, 34.05], [-118.55, 33.95]
  ]]);

  const targetDate = '2015-10-10';
  const dateRange = ee.DateRange(ee.Date(targetDate).advance(-5, 'day'), 
                                ee.Date(targetDate).advance(5, 'day'));

  // 2. Data Acquisition - Try Landsat 8 first (operational in 2015)
  let collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(santaMonicaCoast)
    .filterDate(dateRange)
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  let collectionSize = collection.size().getInfo();
  console.log(`Landsat 8 Images in range: ${collectionSize}`);

  // If no Landsat images, try Sentinel-2
  if (collectionSize === 0) {
    collection = ee.ImageCollection('COPERNICUS/S2')
      .filterBounds(santaMonicaCoast)
      .filterDate(dateRange)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

    collectionSize = collection.size().getInfo();
    console.log(`Sentinel-2 Images in range: ${collectionSize}`);
  }

  // Check for empty collection
  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get best image (closest to target date, least clouds)
  const image = collection.sort('system:time_start', false).first();
  const imageDate = ee.Date(image.get('system:time_start')).format('YYYY-MM-dd').getInfo();
  console.log(`Using image from: ${imageDate}`);

  // 3. Processing - Calculate NDVI for algae detection
  let ndvi;
  if (image.get('SPACECRAFT_ID')) { // Landsat
    ndvi = image.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');
  } else { // Sentinel-2
    ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
  }

  // Mask clouds and land (focus on water areas)
  let waterMask;
  if (image.get('SPACECRAFT_ID')) { // Landsat
    waterMask = image.select('SR_B3').gt(0); // Simple brightness threshold
  } else { // Sentinel-2
    waterMask = image.select('B3').gt(0);
  }

  const maskedNDVI = ndvi.updateMask(waterMask);

  // 4. Calculate statistics
  const stats = maskedNDVI.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: santaMonicaCoast,
    scale: 1000,
    maxPixels: 1e9
  });

  const meanNDVI = stats.get('NDVI_mean').getInfo();
  const pixelCount = stats.get('NDVI_count').getInfo();

  console.log(`Mean NDVI in coastal waters: ${meanNDVI ? meanNDVI.toFixed(3) : 'No data'}`);
  console.log(`Valid pixels: ${pixelCount}`);

  // 5. Validation & Final Answer
  if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
  } else if (meanNDVI === null || meanNDVI === undefined || isNaN(meanNDVI)) {
    console.log("<answer>C3</answer>");
  } else {
    // Algae blooms typically show positive NDVI values in water (unusual)
    // Threshold based on typical water NDVI (negative) vs algae (positive)
    const hasAlgaeBloom = meanNDVI > 0.1; // Conservative threshold
    console.log(`Algae detection threshold: ${meanNDVI > 0.1}`);
    console.log(hasAlgaeBloom ? "<answer>A</answer>" : "<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
